def design(rng, n, p, kind):
    x = rng.normal(size=(n, p))
    if kind == 'paired':
        x[:, 1::2] = 0.97 * x[:, :2 * (p // 2):2] + 0.245 * x[:, 1::2]
    elif kind == 'common':
        x = 0.3 * x + rng.normal(size=(n, 1))
    elif kind == 'ar':
        for j in range(1, p):
            x[:, j] = 0.88 * x[:, j - 1] + 0.475 * x[:, j]
    elif kind == 'rankdef':
        x[:, -2:] = x[:, :2]
    return x / np.linalg.norm(x, axis=0)
